package org.sirius.biotech;

import android.content.*;
import android.provider.ContactsContract;
import android.view.*;
import android.widget.*;
import org.json.*;
import org.sirius.biotech.data.*;
import java.util.*;
import static org.sirius.biotech.OriginalUi.*;

/** MSS attendee pager, search, original rows and detail tabs bound to SBS. */
final class OriginalPeople {
    static View create(MainActivity a)throws Exception{
        Context c=theme(a);FrameLayout root=new FrameLayout(c);root.setBackgroundColor(a.bg);insets(root);inflate(c,"pager_view",root);
        toolbar(a,view(root,"toolbar"),"Participants",()->a.show("home"),"search",ignored->search(a));
        List<View> pages=new ArrayList<>();for(boolean favorites:new boolean[]{false,true}){FrameLayout page=new FrameLayout(c);inflate(c,"attendees_view",page);populate(a,page,favorites,"");pages.add(page);}
        bindPager(view(root,"viewPager"),view(root,"tabLayout"),pages,new String[]{a.tr("Participants"),label(a,"Избранные","Favorites")});return root;
    }
    static void populate(MainActivity a,View page,boolean favorites,String query)throws Exception{
        List<OriginalRecycler.Row> rows=new ArrayList<>();String q=query.toLowerCase(Locale.ROOT);
        for(int i=0;i<a.participants.size();i++){final int index=i;EventRepository.Person person=a.participants.get(i);if(favorites&&!a.isFavorite("people",person.id)||!(person.name+" "+person.organization+" "+person.role).toLowerCase(Locale.ROOT).contains(q))continue;rows.add(parent->row(a,index,true,()->{try{populate(a,page,favorites,query);}catch(Exception e){failed(a,e);}}));}
        list(view(page,"attendeesView"),1,rows);visible(page,"attendeesView",!rows.isEmpty());visible(page,"emptyView",rows.isEmpty());visible(page,"progressView",false);visible(page,"errorView",false);
    }
    static View row(MainActivity a,int index,boolean favorite,Runnable changed)throws Exception{
        Context c=theme(a);EventRepository.Person p=a.participants.get(index);View row=(View)make("com.eventicious.ui.widget.d",new Class<?>[]{Context.class},c);String[] name=p.name.split(" ",2);Class<?> order=cls("com.eventicious.ui.widget.AttendeeNameOrder");
        call(row,"v",new Class<?>[]{String.class,String.class,order,String.class,String.class,cls("com.eventicious.meetings.MeetingStatus")},name[0],name.length>1?name[1]:"",order.getMethod("valueOf",String.class).invoke(null,"FirstName"),p.organization,p.role,null);
        call(row,"setAuthorized",new Class<?>[]{boolean.class},false);call(row,"setFavoriteVisible",new Class<?>[]{boolean.class},favorite);call(row,"setFavorite",new Class<?>[]{boolean.class},a.isFavorite("people",p.id));
        call(row,"setOnFavoriteChangedListener",new Class<?>[]{CompoundButton.OnCheckedChangeListener.class},(CompoundButton.OnCheckedChangeListener)(button,selected)->{
            button.setEnabled(false);callSafeFavorite(row,a.isFavorite("people",p.id));ContentActions.favorite(a,"people",p.id,selected,()->{button.setEnabled(true);callSafeFavorite(row,a.isFavorite("people",p.id));if(changed!=null)changed.run();});
        });ProfilePhotos.load(a,(ImageView)view(row,"avatarView"),p.avatarUrl);row.setContentDescription(p.name);row.setOnClickListener(v->a.person(index));return row;
    }
    static void callSafeFavorite(View row,boolean selected){try{call(row,"setFavorite",new Class<?>[]{boolean.class},selected);}catch(Exception ignored){}}
    static void search(MainActivity a){try{
        Context c=theme(a);LinearLayout root=new LinearLayout(c);root.setOrientation(1);root.setBackgroundColor(a.bg);insets(root);
        View toolbar=(View)make("com.eventicious.toolbar.Toolbar",new Class<?>[]{Context.class,android.util.AttributeSet.class},c,null);root.addView(toolbar);toolbar(a,toolbar,"Participants",()->a.show("Participants"),null,null);
        FrameLayout page=new FrameLayout(c);inflate(c,"attendees_search_view",page);root.addView(page,new LinearLayout.LayoutParams(-1,0,1));EditText input=(EditText)view(view(page,"inputView"),"searchInputView");View list=view(page,"listView");
        Runnable update=()->{try{List<OriginalRecycler.Row> rows=new ArrayList<>();String q=input.getText().toString().toLowerCase(Locale.ROOT);for(int i=0;i<a.participants.size();i++){final int index=i;EventRepository.Person p=a.participants.get(i);if((p.name+" "+p.role+" "+p.organization).toLowerCase(Locale.ROOT).contains(q))rows.add(parent->row(a,index,true,null));}list(list,1,rows);visible(page,"emptyView",rows.isEmpty());visible(page,"loadingView",false);}catch(Exception e){failed(a,e);}};
        input.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int x,int n,int f){}public void onTextChanged(CharSequence s,int x,int before,int count){update.run();}public void afterTextChanged(android.text.Editable e){}});update.run();a.sceneBack=()->a.show("Participants");a.setContentView(root);
    }catch(Exception e){failed(a,e);}}
    static boolean speaks(EventRepository.Person p,EventRepository.Session s){String value=s.speaker.toLowerCase(Locale.ROOT).replace('ё','е');String[] parts=p.name.toLowerCase(Locale.ROOT).replace('ё','е').split("\\s+");if(parts.length<2)return false;for(String part:parts)if(part.length()>1&&!value.contains(part))return false;return true;}
    static View details(MainActivity a,int index)throws Exception{
        EventRepository.Person person=a.participants.get(index);Context c=theme(a);LinearLayout root=scene(a,"attendee_view");toolbar(a,view(root,"toolbar"),"Participant",()->a.show("Participants"),null,null);visible(root,"loadingView",false);View header=view(root,"headerView");call(header,"setName",new Class<?>[]{String.class},person.name);ProfilePhotos.load(a,(ImageView)view(header,"avatarView"),person.avatarUrl);View portrait=view(header,"avatarView");portrait.setOutlineProvider(new android.view.ViewOutlineProvider(){public void getOutline(View v,android.graphics.Outline outline){outline.setRoundRect(0,0,v.getWidth(),v.getHeight(),a.dp(16));}});portrait.setClipToOutline(true);view(header,"avatarView").setOnClickListener(v->{if(!person.avatarUrl.isEmpty())ContentActions.photo(a,person.avatarUrl,person.name,()->a.person(index));});
        List<View> pages=new ArrayList<>();List<String> labels=new ArrayList<>();FrameLayout info=new FrameLayout(c);inflate(c,"attendee_info_view",info);List<OriginalRecycler.Row> fields=new ArrayList<>();
        fields.add(parent->{View group=inflate(c,"attendee_field_group_view",parent,false);((TextView)group.findViewById(android.R.id.text1)).setText(label(a,"Информация","Information"));((ImageView)group.findViewById(android.R.id.icon)).setImageDrawable(drawable(c,"icon_profile_24"));return group;});
        if(!person.organization.isEmpty())fields.add(parent->field(c,parent,label(a,"Организация","Organization"),person.organization,false));if(!person.role.isEmpty())fields.add(parent->field(c,parent,label(a,"Должность","Position"),person.role,false));JSONObject raw=((ServerRepository)a.repository).raw("people",person.id);String bio=raw.optString("bio");if(!bio.isEmpty()&&!bio.equals(person.role))fields.add(parent->field(c,parent,label(a,"О себе","About"),bio,false));String url=raw.optString("source_url",raw.optString("url"));if(!url.isEmpty())fields.add(parent->{View row=field(c,parent,label(a,"Сайт","Website"),url,true);row.setOnClickListener(v->ContentActions.url(a,url));return row;});
        if(!person.id.equals(a.ownPersonId))fields.add(parent->{View row=inflate(c,"catalog_item_text",parent,false);((TextView)row.findViewById(android.R.id.text1)).setText(a.tr("Save contact"));row.setOnClickListener(v->contact(a,person,bio));return row;});list(view(info,"infoView"),1,fields);pages.add(info);labels.add(label(a,"Информация","Information"));
        List<OriginalRecycler.Row> sessions=new ArrayList<>();for(int n=0;n<a.sessions.size();n++){final int si=n;EventRepository.Session s=a.sessions.get(n);if(speaks(person,s))sessions.add(parent->{View row=inflate(c,"attendee_session_view",parent,false);((TextView)row.findViewById(android.R.id.text1)).setText(s.title);((TextView)row.findViewById(android.R.id.text2)).setText(s.time+" · "+s.room);row.setOnClickListener(v->a.session(si));return row;});}
        if(!sessions.isEmpty()){FrameLayout sessionPage=new FrameLayout(c);inflate(c,"attendee_meeting_view",sessionPage);list(view(sessionPage,"meetingView"),1,sessions);pages.add(sessionPage);labels.add(label(a,"Сессии","Sessions"));}
        boolean canTalk=!person.archive&&!person.id.equals(a.ownPersonId);FrameLayout chat=null;int chatIndex=-1;
        if(canTalk){chat=new FrameLayout(c);pages.add(chat);chatIndex=pages.size()-1;labels.add(label(a,"Сообщения","Messages"));FrameLayout meetings=new FrameLayout(c);inflate(c,"attendee_meeting_view",meetings);List<OriginalRecycler.Row> initial=new ArrayList<>();initial.add(parent->{View row=inflate(c,"attendee_meeting_item_empty",parent,false);row.findViewById(android.R.id.button1).setOnClickListener(v->OriginalMeetings.propose(a,index));return row;});list(view(meetings,"meetingView"),1,initial);pages.add(meetings);labels.add(a.tr("Meetings"));loadMeetings(a,meetings,index);}
        View pager=pager(c,view(header,"tabLayout"),pages,labels.toArray(new String[0]));ViewGroup host=(ViewGroup)view(root,"viewShifter");host.setAlpha(1);host.addView(pager,new FrameLayout.LayoutParams(-1,-1));
        if(chat!=null){FrameLayout chatHost=chat;final int position=chatIndex;final boolean[] started={false};Object listener=proxy("u8.e",args->{if(!started[0]&&((Integer)call(pager,"getCurrentItem",new Class<?>[]{}))==position){started[0]=true;final int owner=a.accountGeneration;a.network.execute(()->{try{JSONObject response=a.api.request("POST","/chats",new JSONObject().put("person_id",person.id));a.runOnUiThread(()->{if(owner!=a.accountGeneration||!root.isAttachedToWindow())return;try{View actual=ServerChatScreen.create(a,response.getString("id"),person.name);visible(actual,"toolbar",false);chatHost.addView(actual,new FrameLayout.LayoutParams(-1,-1));}catch(Exception e){failed(a,e);}});}catch(Exception e){a.runOnUiThread(()->{started[0]=false;a.toast("Unable to open conversation. Please retry.");});}});}return null;});call(pager,"b",new Class<?>[]{cls("u8.e")},listener);}
        View options=view(header,"moreButton");options.setVisibility(person.id.equals(a.ownPersonId)?View.GONE:View.VISIBLE);options.setAlpha(1);options.setOnClickListener(v->{PopupMenu menu=new PopupMenu(c,options);menu.getMenu().add(a.isFavorite("people",person.id)?a.tr("Contact saved"):a.tr("Save contact")).setOnMenuItemClickListener(item->{ContentActions.favorite(a,"people",person.id,!a.isFavorite("people",person.id),()->{});return true;});menu.getMenu().add(label(a,"Добавить в контакты телефона","Add to phone contacts")).setOnMenuItemClickListener(item->{contact(a,person,bio);return true;});menu.show();});a.sceneBack=()->a.show("Participants");return root;
    }
    static void loadMeetings(MainActivity a,View page,int index){EventRepository.Person person=a.participants.get(index);int owner=a.accountGeneration;a.network.execute(()->{try{JSONArray items=a.api.request("GET","/meetings",null).getJSONArray("items");a.runOnUiThread(()->{if(owner!=a.accountGeneration)return;try{List<OriginalRecycler.Row> rows=new ArrayList<>();for(int n=0;n<items.length();n++){JSONObject m=items.getJSONObject(n);if(!OriginalMeetings.peer(a,m).equals(person.id))continue;rows.add(parent->{String state=m.optString("status");View row=inflate(theme(a),state.equals("accepted")?"attendee_meeting_item_confirmed":state.equals("pending")?"attendee_meeting_item_wait_confirmation":"attendee_meeting_item_canceled",parent,false);text(row,"subjectView",m.optString("title"));if(row.findViewById(id(theme(a),"dateView","id"))!=null)text(row,"dateView",OriginalMeetings.parse(m.optString("starts_at")).format(java.time.format.DateTimeFormatter.ofPattern("d MMMM · HH:mm",Locale.getDefault())));if(row.findViewById(id(theme(a),"locationView","id"))!=null)text(row,"locationView",m.optString("location"));row.setOnClickListener(v->OriginalMeetings.details(a,m));return row;});}rows.add(parent->{View row=inflate(theme(a),"attendee_meeting_item_empty",parent,false);row.findViewById(android.R.id.button1).setOnClickListener(v->OriginalMeetings.propose(a,index));return row;});list(view(page,"meetingView"),1,rows);}catch(Exception e){failed(a,e);}});}catch(Exception ignored){}});}
    static void contact(MainActivity a,EventRepository.Person p,String bio){try{Intent intent=new Intent(Intent.ACTION_INSERT).setType(ContactsContract.Contacts.CONTENT_TYPE).putExtra(ContactsContract.Intents.Insert.NAME,p.name).putExtra(ContactsContract.Intents.Insert.COMPANY,p.organization).putExtra(ContactsContract.Intents.Insert.JOB_TITLE,p.role).putExtra(ContactsContract.Intents.Insert.NOTES,bio);a.startActivity(intent);}catch(ActivityNotFoundException e){a.toast("Contacts app is unavailable");}}
}
